sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-32: FLEET - Prevent Double Booking (insert and update; assignment happens on update)
    if (current.assigned_vehicle.nil() || current.start_datetime.nil() || current.end_datetime.nil()) {
        return;
    }
    var TERMINAL = ['COMPLETED', 'CANCELLED', 'REJECTED', 'NO_SHOW', 'INTERRUPTED'];
    if (TERMINAL.indexOf(current.getValue('reservation_state')) > -1) {
        return;
    }
    var relevant = current.operation() == 'insert' || current.assigned_vehicle.changes() ||
        current.start_datetime.changes() || current.end_datetime.changes();
    if (!relevant) {
        return;
    }
    var free = new FleetAvailability().isVehicleFree(current.getValue('assigned_vehicle'),
        new GlideDateTime(current.getValue('start_datetime')), new GlideDateTime(current.getValue('end_datetime')),
        current.getUniqueValue());
    if (!free) {
        gs.addErrorMessage('Vehicle ' + current.assigned_vehicle.getDisplayValue() +
            ' is not available for this period (booked, in maintenance, or documents expire).');
        current.setAbortAction(true);
    }
})(current, previous);
